import gradio as gr
import re
from rag_engine import answer_with_rag

LOGO_B64 = ""

EXAMPLES = [
    "What percent of the final grade is the HCI group project?",
    "What is the minimum passing grade for MSAI-631?",
    "What are the required deliverables for the HCI group project?",
    "What is the late work policy for assignments?",
    "What does human-centered AI mean?",
    "How is usability defined in this course?",
]

FOLLOW_UP = (
    "\n\n---\nWhat else would you like to know? Try asking about:\n"
    "- Grading or assignment weights\n"
    "- Deadlines and the late work policy\n"
    "- The HCI group project requirements\n"
    "- Key course concepts"
)

GREETING = (
    "👋 Hello! Welcome to the MSAI-631 Course Companion!\n\n"
    "I search your actual course documents to find accurate answers.\n\n"
    "How to use:\n"
    "  • Type a question and press Enter or click Ask\n"
    "  • Click any example button below to ask instantly\n"
    "  • Use Clear to reset | Dark for dark mode | Mic for voice\n\n"
    "What would you like to know today?"
)

def render_bubbles(history, dark=False):
    bot_style = ("align-self:flex-start;background:#1e4976;color:#e8f0fe;" if dark else "align-self:flex-start;background:#1b3a5c;color:#fff;")
    user_style = ("align-self:flex-end;background:#f0c040;color:#0d1b2a;" if dark else "align-self:flex-end;background:#f0c040;color:#1a1a2e;")
    status_style = ("align-self:center;color:#7ab0d4;" if dark else "align-self:center;color:#5a7fa8;")
    chat_bg = ("background:#112233;border:1px solid #1e3a5f;" if dark else "background:#fff;border:1px solid #c5d5e8;")
    bbot = "border-radius:2px 12px 12px 12px;padding:9px 13px;max-width:75%;font-size:0.88rem;line-height:1.6;white-space:pre-wrap;word-break:break-word;margin-bottom:2px;"
    buser = "border-radius:12px 12px 2px 12px;padding:9px 13px;max-width:55%;font-size:0.88rem;line-height:1.6;font-weight:600;white-space:pre-wrap;word-break:break-word;margin-bottom:2px;"
    bstatus = "font-size:0.8rem;font-style:italic;padding:3px 0;"
    html = ""
    for role, msg in history:
        s = msg.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\n","<br>")
        s = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', s)
        if role == "assistant":
            html += f'<div style="{bot_style}{bbot}">{s}</div>'
        elif role == "status":
            html += f'<div style="{status_style}{bstatus}">{s}</div>'
        else:
            html += f'<div style="{user_style}{buser}">{s}</div>'
    scr = '<iframe style="display:none;width:0;height:0;" onload="(function(){var p=document.getElementById(\'chatbox\');if(p){p.scrollTop=p.scrollHeight;}})()" src="about:blank"></iframe>'
    return (f'<div id="chatbox" style="{chat_bg}border-radius:12px;padding:12px;height:310px;overflow-y:auto;display:flex;flex-direction:column;gap:8px;">{html}{scr}</div>')

def respond(message, history, dark):
    q = (message or "").strip()
    if not q:
        return render_bubbles(history, dark), history, ""
    ql = q.lower()
    history = history + [("user", q)]
    yield render_bubbles(history + [("status", "🔍 Searching course materials...")], dark), history, ""
    if ql in {"hi", "hello", "hey"}:
        reply = "Hello! 👋 What would you like to know about MSAI-631?\n\nType a question or click an example below."
    elif "thank" in ql:
        reply = "You're welcome! 😊 Feel free to ask anything else."
    else:
        reply = answer_with_rag(q)
        if not reply or len(reply.strip()) < 10:
            reply = "I could not find a confident answer.\n\nTry rephrasing, or ask about grading, deadlines, or the HCI project."
        else:
            reply = reply + FOLLOW_UP
    history = history + [("assistant", reply)]
    yield render_bubbles(history, dark), history, ""

def use_example(example, history, dark):
    history = history + [("user", example)]
    yield render_bubbles(history + [("status", "🔍 Searching course materials...")], dark), history
    reply = answer_with_rag(example)
    if not reply or len(reply.strip()) < 10:
        reply = "I could not find a confident answer. Try rephrasing."
    else:
        reply = reply + FOLLOW_UP
    history = history + [("assistant", reply)]
    yield render_bubbles(history, dark), history

def clear_chat(dark):
    fresh = [("assistant", GREETING)]
    return render_bubbles(fresh, dark), fresh

def toggle_dark(history, dark):
    new_dark = not dark
    chat = render_bubbles(history, new_dark)
    if new_dark:
        css = f'<style>{CSS_DARK}</style>'
        lbl = "☀️ Light"
        title = '<div style="text-align:center;margin:0 0 4px 0;"><h1 style="color:#f0c040;font-size:1.5rem;font-weight:800;margin:0;">MSAI-631 Course Companion</h1><p style="color:#c8d6e5;font-size:0.82rem;margin:2px 0 0 0;">Ask me anything about your course. <strong>Type below or click an example.</strong></p></div>'
    else:
        css = f'<style>{CSS_LIGHT}</style>'
        lbl = "🌙 Dark"
        title = '<div style="text-align:center;margin:0 0 4px 0;"><h1 style="color:#1b3a5c;font-size:1.5rem;font-weight:800;margin:0;">MSAI-631 Course Companion</h1><p style="color:#2c4a6e;font-size:0.82rem;margin:2px 0 0 0;">Ask me anything about your course. <strong>Type below or click an example.</strong></p></div>'
    return chat, css, gr.update(value=lbl), title, new_dark

